import{z as i,x as s,o as l,c as p,q as t,j as A,D as B,d as a,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"MoE 的低精度","description":"","frontmatter":{"title":"MoE 的低精度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-moe-lowprecision.md","filePath":"llm/num-moe-lowprecision.md","lastUpdated":1791413859000}'),m={name:"llm/num-moe-lowprecision.md"};function d(D,E,F,c,C,u){const o=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="moe-的低精度" tabindex="-1">MoE 的低精度 <a class="header-anchor" href="#moe-的低精度" aria-label="Permalink to &quot;MoE 的低精度&quot;">​</a></h1><div class="epigraph"><p>MoE 里最贵的低精度事故不在专家的 GEMM，而在路由：一个 logit 的舍入偏差，掀翻的是整张负载表。</p><footer>—— 据 DeepSeek-AI, DeepSeek-V3 Technical Report, 2024 的 FP8 训练设计整理</footer></div><p><a href="/llm/num-outlier-atlas">上一课</a>的图谱在混合专家上多出一个维度：同一个模型里，激活分布按专家分裂。专家 GEMM 的低精度与稠密模型同类——格式、尺子、舍入三份账照算；MoE 特有的是门控与均衡的数值。负载均衡的机制与无辅助损失的偏置调节分别在 <a href="/llm/moe-load-balance">MoE 负载均衡</a> 与 <a href="/llm/aux-loss-free-balancing">无辅助损失的均衡</a> 写过，本课只写数值面：哪些量必须保宽，专家级缩放怎么做，通信格式怎么签合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>路由是 argmax：每个 token 的 top-\\(k\\) 专家由门控 logits 的排序决定。排序对扰动过敏——两个近邻专家的 logit 差小于量化噪声时，舍入方向决定谁入选。这与前几课的噪声有本质区别：GEMM 的舍入误差是零均值的，单个选择的翻转是<strong>离散事件</strong>，且后果是系统性的——专家负载突变，均衡偏置跟着调节，负载变化又改各专家的 amax 统计，第二课延迟缩放「amax 平滑」的假设在这里被路由亲手打破。闭环是：量化噪声 → 路由翻转 → 负载振荡 → 尺度抖动 → 更大的量化噪声。</p><p><span class="marginnote">「argmax」翻译成白话就是「挑出分数最大的那一个」：路由器给每个专家打分（logit），top-\\(k\\) 选择把分数最高的 \\(k\\) 个专家挑出来处理这个 token。它只看名次、不看分差——所以再小的舍入误差，只要改变了名次，选中的专家就整个换掉，这就是「离散翻转」的含义。</span></p><p>第二层困难在统计量：专家按 token 切分后，每个专家在自己的 expert parallel 组里拿到的样本远少于全 batch，per-expert 的 amax 与分位数天然抖；冷门专家的统计更稀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层保精度，把「必须宽」的清单划到专家机制上。路由 logits、softmax 门控与 top-\\(k\\) 选择保 BF16 或 FP32——这是清单里不可谈判的一项。专家 GEMM 走 FP8，但缩放粒度要细：DeepSeek-V3 的配方是细粒度块缩放（按 128 通道或固定元素数分块），因为不同专家的分布差异大，per-tensor 尺度会被最野的专家绑架。保宽清单还有：共享专家、嵌入、路由器本体、输出头与首尾若干层（首层激活格局未定型，尾层直接接损失）。</p><p><span class="marginnote">直觉类比：per-tensor 缩放像全公司共用一个报销上限——最能花钱的部门一超标，全公司的额度都被迫收紧，其他部门跟着受穷；按 128 通道分块则像每个部门各有各的预算，最「野」的专家再夸张，也只绑架自己那一小块的精度。</span></p>',10)),(l(),A(n,null,{default:B(()=>[r(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%9A%90%E7%8A%B6%E6%80%81%EF%BC%88%E5%AE%BD%E6%A0%BC%E5%BC%8F%EF%BC%89%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%20logits%EF%BC%9A%E4%BF%9D%E5%AE%BD%E8%AE%A1%E7%AE%97%22%5D%0A%20%20R%20--%3E%20TOP%5B%22top-k%20%E9%80%89%E6%8B%A9%EF%BC%9A%E4%BF%9D%E5%AE%BD%20argmax%22%5D%0A%20%20TOP%20--%3E%20DISP%5B%22%E6%8C%89%E4%B8%93%E5%AE%B6%E5%88%86%E5%8F%91%EF%BC%88FP8%20%E4%B9%8B%E5%89%8D%EF%BC%89%22%5D%0A%20%20DISP%20--%3E%20E1%5B%22%E4%B8%93%E5%AE%B6%20GEMM%EF%BC%9AFP8%20%2B%20%E7%BB%86%E7%B2%92%E5%BA%A6%E5%9D%97%E7%BC%A9%E6%94%BE%22%5D%0A%20%20E1%20--%3E%20A2A%5B%22All2All%EF%BC%9A%E9%80%9A%E4%BF%A1%20dtype%20%E5%85%A8%E9%9B%86%E7%BE%A4%E7%AD%BE%E5%90%88%E5%90%8C%22%5D%0A%20%20A2A%20--%3E%20COMB%5B%22%E5%8A%A0%E6%9D%83%E5%90%88%E5%B9%B6%EF%BC%88%E5%AE%BD%E7%B4%AF%E5%8A%A0%EF%BC%89%22%5D%0A%20%20COMB%20--%3E%20OUT%5B%22%E5%9B%9E%E6%AE%8B%E5%B7%AE%E6%B5%81%22%5D%0A%20%20E1%20--%3E%20STAT%5B%22%E4%B8%93%E5%AE%B6%E7%BA%A7%20amax%EF%BC%9A%E5%88%86%E7%BB%84%E5%86%85%E5%BD%92%E7%BA%A6%E8%BF%9B%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"专家级统计与检查点：amax 按专家分片组归约（第二课的分布式合同加上专家维），scale 与偏置调节量同批存档，否则续训的负载表接不上。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("为什么 argmax 保宽是机械要求而不是保守习惯：softmax 门控的权重由 logit 差决定，翻转改变的不是某个系数的精度，而是"),e("strong",null,"计算图走哪条边"),a("——被换掉的专家输出完全不同，误差不进入「小扰动」框架。这也解释了为什么负载指标必须与损失一起看：路由噪声在损失上可能被平均，在专家负载方差上却先行恶化，等损失可见时闭环已转了几圈。细粒度缩放在 MoE 收益更大的机制在分母：块越小，单点绑架影响的面越小；专家分布的离散差异让 per-tensor 方案的绑架概率按专家数放大。")],-1)),(l(),A(n,null,{default:B(()=>[r(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20N1%5B%22%E9%87%8F%E5%8C%96%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20N2%5B%22%E8%BF%91%E9%82%BB%E4%B8%93%E5%AE%B6%20logit%20%E5%B7%AE%E8%A2%AB%E5%90%9E%E6%B2%A1%22%5D%0A%20%20N2%20--%3E%20N3%5B%22%E8%B7%AF%E7%94%B1%E7%BF%BB%E8%BD%AC%EF%BC%9Atoken%20%E6%8D%A2%E4%B8%93%E5%AE%B6%22%5D%0A%20%20N3%20--%3E%20N4%5B%22%E4%B8%93%E5%AE%B6%E8%B4%9F%E8%BD%BD%E7%AA%81%E5%8F%98%EF%BC%8C%E5%81%8F%E7%BD%AE%E8%B7%9F%E7%9D%80%E8%B0%83%E8%8A%82%22%5D%0A%20%20N4%20--%3E%20N5%5B%22%E5%90%84%E4%B8%93%E5%AE%B6%20amax%20%E7%BB%9F%E8%AE%A1%E6%BC%82%E7%A7%BB%22%5D%0A%20%20N5%20--%3E%20N6%5B%22%E5%BB%B6%E8%BF%9F%E7%BC%A9%E6%94%BE%E7%9A%84%20scale%20%E6%8A%96%E5%8A%A8%22%5D%0A%20%20N6%20--%3E%20N1%0A%20%20N4%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%E5%8F%A3%EF%BC%9A%E8%B4%9F%E8%BD%BD%E6%96%B9%E5%B7%AE%E4%B8%8E%E5%81%8F%E7%BD%AE%E6%8C%AF%E8%8D%A1%E5%85%88%E4%BA%8E%E6%8D%9F%E5%A4%B1%E6%81%B6%E5%8C%96%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">常见误区：看到损失曲线没涨就以为路由数值没问题。这个闭环里，路由噪声最先表现在专家负载方差和均衡偏置的振荡上，要转几圈才传导到损失；只盯损失等于等火烧到门口才看烟感。</span></p><p><span class="marginnote">DeepSeek-V3 报告的 FP8 混合精度框架保留 BF16 的清单包括路由、嵌入、输出头与首尾层，正与「离散事件不进噪声框架」的机制一致；细粒度累加则把 FP8 的精度损失压到与 BF16 训练同量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>全 FP8 的 MoE 配方要在小规模上先验两件事：负载指标（专家负载方差、偏置调节量的振荡）与每专家溢出计数，都稳了再放大。通信 FP8 需要全集群对同一缩放约定签字——不同实现混布等于无定义（第九课的跨硬件合同的特例）。专家并行的重构排布会改变统计窗口，压测要按真实并行度做。最后，别把「MoE 低精度」简化成「专家权重 4-bit」：推理侧的专家量化另有一条线，训练态的门控与缩放合同才是本课的地盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路由是 argmax：量化噪声引发离散翻转，经负载与缩放形成正反馈闭环，门控必须保宽。</li><li>专家 GEMM 可 FP8，缩放要细粒度分块，per-tensor 会被最野专家绑架。</li><li>专家级 amax 按分片组归约，scale 与均衡偏置进检查点。</li><li>负载指标先于损失恶化；监控面要看专家负载方差与偏置振荡。</li><li>通信 dtype 全集群签同一合同。</li><li>出处：DeepSeek-AI, DeepSeek-V3 Technical Report, 2024；MoE 负载均衡与无辅助损失均衡的既有口径。</li></ul>',6))])}const M=i(m,[["render",d]]);export{x as __pageData,M as default};
